                <!-- Your Item Section -->
                <tr>
                  <td style="padding: 20px;">
                    <p style="margin: 0 0 12px 0; color: #6b7280; font-size: 12px; text-transform: uppercase; letter-spacing: 0.5px;">Your Item</p>
                    <div style="background-color: rgba(0, 0, 0, 0.5); border: 1px solid rgba(6, 182, 212, 0.2); border-radius: 8px; padding: 16px;">
                      <code style="color: #22d3ee; font-family: 'Courier New', monospace; font-size: 13px; word-break: break-all; line-height: 1.5;">{{stockItem}}</code>
                    </div>
