                  {product.stock.toLocaleString()}
                </span>
              </div>
            </div>
          </div>

          <div className="relative rounded-xl overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-b from-[hsl(0_0%_9%)] to-[hsl(0_0%_6%)]" />
            <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_50%_0%,hsl(var(--primary)/0.06),transparent_60%)]" />
            <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-primary/30 to-transparent" />
            <div className="absolute inset-0 border border-white/[0.06] rounded-xl pointer-events-none" />

            <div className="relative p-4 space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-sm text-[hsl(0_0%_50%)] font-medium">Quantity</span>
                <div className="flex items-center gap-1.5">
                  <Button
                    size="icon"
                    variant="outline"
