                  <div className="flex items-center justify-center min-w-[3rem] rounded-md bg-white/[0.06] border border-white/[0.1] min-h-9 px-3">
                    <span className="text-white font-bold text-sm tabular-nums">
                      {quantity}
                    </span>
                  </div>
                  <Button
                    size="icon"
                    variant="outline"
                    onClick={() => handleQuantityChange(1)}
                    disabled={quantity >= maxQuantity}
                    className="bg-white/[0.04] border-white/[0.1] text-white/70"
                    data-testid="button-increase-quantity"
                  >
                    <Plus className="w-3.5 h-3.5" />
                  </Button>
                </div>
              </div>

              <div className="h-px bg-gradient-to-r from-transparent via-white/[0.08] to-transparent" />

              <div className="flex items-center justify-between">
                <span className="text-sm text-[hsl(0_0%_50%)] font-medium">Total</span>
                <div className="flex items-baseline gap-1">
