  --shadow-2xs: 0px 2px 0px 0px hsl(0 0% 0% / 0.00);
  --shadow-xs: 0px 2px 0px 0px hsl(0 0% 0% / 0.00);
  --shadow-sm: 0px 2px 0px 0px hsl(0 0% 0% / 0.00), 0px 1px 2px -1px hsl(0 0% 0% / 0.00);
  --shadow: 0px 2px 0px 0px hsl(0 0% 0% / 0.00), 0px 1px 2px -1px hsl(0 0% 0% / 0.00);
  --shadow-md: 0px 2px 0px 0px hsl(0 0% 0% / 0.00), 0px 2px 4px -1px hsl(0 0% 0% / 0.00);
  --shadow-lg: 0px 2px 0px 0px hsl(0 0% 0% / 0.00), 0px 4px 6px -1px hsl(0 0% 0% / 0.00);
  --shadow-xl: 0px 2px 0px 0px hsl(0 0% 0% / 0.00), 0px 8px 10px -1px hsl(0 0% 0% / 0.00);
  --shadow-2xl: 0px 2px 0px 0px hsl(0 0% 0% / 0.00);

/* Fallback for older browsers */
  --sidebar-primary-border: hsl(var(--sidebar-primary));
  --sidebar-primary-border: hsl(from hsl(var(--sidebar-primary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  /* Fallback for older browsers */
  --sidebar-accent-border: hsl(var(--sidebar-accent));
  --sidebar-accent-border: hsl(from hsl(var(--sidebar-accent)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  /* Fallback for older browsers */
  --primary-border: hsl(var(--primary));
  --primary-border: hsl(from hsl(var(--primary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  /* Fallback for older browsers */
  --secondary-border: hsl(var(--secondary));
  --secondary-border: hsl(from hsl(var(--secondary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  /* Fallback for older browsers */
  --muted-border: hsl(var(--muted));
  --muted-border: hsl(from hsl(var(--muted)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  /* Fallback for older browsers */
  --accent-border: hsl(var(--accent));
  --accent-border: hsl(from hsl(var(--accent)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);

  /* Fallback for older browsers */
  --destructive-border: hsl(var(--destructive));
  --destructive-border: hsl(from hsl(var(--destructive)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
  }
}

/**
 * Using the elevate system.
 * Automatic contrast adjustment.
 *
 * <element className="hover-elevate" />
 * <element className="active-elevate-2" />
 *
 * // Using the tailwind utility when a data attribute is "on"
 * <element className="toggle-elevate data-[state=on]:toggle-elevated" />
 * // Or manually controlling the toggle state
 * <element className="toggle-elevate toggle-elevated" />
 *
 * Elevation systems have to handle many states.
 * - not-hovered, vs. hovered vs. active  (three mutually exclusive states)
 * - toggled or not
 * - focused or not (this is not handled with these utilities)
 *
 * Even without handling focused or not, this is six possible combinations that
 * need to be distinguished from eachother visually.
 */
@layer utilities {

  /* Hide ugly search cancel button in Chrome until we can style it properly */
  input[type="search"]::-webkit-search-cancel-button {
    @apply hidden;
  }

  /* Placeholder styling for contentEditable div */
  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  /* .no-default-hover-elevate/no-default-active-elevate is an escape hatch so consumers of
   * buttons/badges can remove the automatic brightness adjustment on interactions
   * and program their own. */
  .no-default-hover-elevate {}

  .no-default-active-elevate {}


  /**
   * Toggleable backgrounds go behind the content. Hoverable/active goes on top.
   * This way they can stack/compound. Both will overlap the parent's borders!
   * So borders will be automatically adjusted both on toggle, and hover/active,
   * and they will be compounded.
   */
  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    /*border-radius: inherit;   match rounded corners */
    border-radius: inherit;
    z-index: -1;
    /* sits behind content but above backdrop */
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
  .border.toggle-elevate::before {
    inset: -1px;
  }

  /* Does not work on elements with overflow:hidden! */
  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    /*border-radius: inherit;   match rounded corners */
    border-radius: inherit;
    z-index: 999;
    /* sits in front of content */
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate:not(.no-hover-interaction-elevate)::after {
    inset: -1px;
  }

  /* Custom scrollbar for dark theme */
  .custom-scrollbar::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  .custom-scrollbar::-webkit-scrollbar-track {
    background: transparent;
  }

  .custom-scrollbar::-webkit-scrollbar-thumb {
    background: hsl(var(--muted));
    border-radius: 3px;
  }

  .custom-scrollbar::-webkit-scrollbar-thumb:hover {
    background: hsl(var(--muted-foreground) / 0.5);
  }

  /* Animated gradient background - uses theme background */
  .animated-gradient {
    background: hsl(var(--background));
  }

  @keyframes gradient-shift {
    0% {
      background-position: 0% 50%;
    }
    50% {
      background-position: 100% 50%;
    }
    100% {
      background-position: 0% 50%;
    }
  }

  @keyframes glowSwipe {
    0% {
      transform: translateX(-100%);
    }
    50% {
      transform: translateX(100%);
    }
    100% {
      transform: translateX(-100%);
    }
  }

  /* Cyan glow effect */
  .cyan-glow {
    box-shadow: 0 0 20px hsl(185 80% 50% / 0.15),
                0 0 40px hsl(185 70% 45% / 0.1);
  }

  /* Dot pattern background that follows theme */
  .dot-pattern {
    background-image: radial-gradient(circle at 1px 1px, hsl(var(--primary) / 0.15) 1px, transparent 0);
    background-size: 40px 40px;
  }

  /* Glow effect for cards - Cyan theme */
  .card-glow {
    position: relative;
    transition: all 0.3s ease;
  }

  .card-glow::before {
    content: "";
    position: absolute;
    inset: -1px;
    background: linear-gradient(
      135deg,
      hsl(185 80% 50% / 0.15) 0%,
      hsl(185 70% 45% / 0.08) 50%,
      hsl(185 75% 50% / 0.12) 100%
    );
    border-radius: inherit;
    z-index: -1;
    opacity: 0;
    transition: opacity 0.3s ease;
  }

  .card-glow:hover::before {
    opacity: 1;
  }

  .card-glow:hover {
    box-shadow: 0 2px 12px hsl(185 80% 50% / 0.15),
                0 4px 20px hsl(185 70% 45% / 0.1);
  }

  /* Line clamp utilities */
  .line-clamp-2 {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  /* Product card content styling */
  .product-content {
    background: hsl(var(--card));
    position: relative;
  }

  /* Title container styling - uses theme colors */
  .title-container {
    background: hsl(var(--card));
    border: 1px solid hsl(var(--border));
  }

  /* Price glow effect */
  .price-glow {
    text-shadow: 0 0 10px hsl(185 80% 50% / 0.5);
  }

  /* Stock badge styling - uses theme colors */
  .stock-badge {
    background: hsl(var(--muted));
    border: 1px solid hsl(var(--border));
  }
}

/* reCAPTCHA container wrapper */
.recaptcha-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  z-index: 1;
}

/* Responsive scaling for small screens */
@media (max-width: 400px) {
  .recaptcha-wrapper {
    transform: scale(0.9);
    transform-origin: center center;
  }
}

/* Center reCAPTCHA challenge popup on mobile */
@media (max-width: 640px) {
  /* Target Google reCAPTCHA challenge container - only containers with inline z-index styles */
  body > div[style*="z-index"]:not([data-radix-portal]):not([class]):not(#root) {
    left: 0 !important;
    right: 0 !important;
    margin-left: auto !important;
    margin-right: auto !important;
    width: 100vw !important;
    display: flex !important;
    justify-content: center !important;
    align-items: flex-start !important;
    padding-top: 10vh !important;
  }

  body > div[style*="z-index"]:not([data-radix-portal]):not([class]):not(#root) > div {
    position: relative !important;
    left: auto !important;
    right: auto !important;
    transform: none !important;
    margin: 0 auto !important;
  }

  /* Scale down the reCAPTCHA challenge if needed */
  body > div[style*="z-index"]:not([data-radix-portal]):not([class]):not(#root) > div > iframe {
    max-width: 95vw !important;
  }
}

/* reCAPTCHA z-index fix - ensure challenge popup appears above modals */
/* Google reCAPTCHA creates elements with very high z-index that need to be above dialog overlays */
iframe[src*="recaptcha"],
iframe[title*="recaptcha"],
div[style*="z-index: 2000000000"],
div[style*="z-index: 1000000000"],
div[style*="z-index: 9999999"],
div[style*="z-index:2000000000"],
div[style*="z-index:1000000000"] {
  z-index: 2147483647 !important;
  pointer-events: auto !important;
}

/* Target all Google reCAPTCHA containers specifically */
body > div:not([data-radix-portal]):not([class]) {
  z-index: 2147483647 !important;
  pointer-events: auto !important;
}

/* Target the reCAPTCHA challenge iframe container specifically */
body > div > div > iframe[title="recaptcha challenge expires in two minutes"],
body > div > div > iframe[title*="recaptcha"] {
  z-index: 2147483647 !important;
  pointer-events: auto !important;
}

/* Ensure reCAPTCHA challenge overlay and content are clickable */
div[style*="visibility: visible"][style*="position: fixed"] {
  pointer-events: auto !important;
  z-index: 2147483647 !important;
}

/* Google reCAPTCHA challenge wrapper - uses inline styles with very high z-index */
body > div[style*="position: absolute"][style*="z-index"],
body > div[style*="position: fixed"][style*="z-index"] {
  z-index: 2147483647 !important;
  pointer-events: auto !important;
}

/* Prevent radix dialog overlay from blocking reCAPTCHA */
[data-radix-portal] [role="dialog"] {
  pointer-events: auto;
}

/* Ensure the reCAPTCHA iframe itself is always clickable */
.recaptcha-wrapper iframe {
  pointer-events: auto !important;
}

/* Custom scrollbar styling for a cleaner look */
.custom-scrollbar::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

.custom-scrollbar::-webkit-scrollbar-track {
  background: transparent;
}

.custom-scrollbar::-webkit-scrollbar-thumb {
  background: hsl(var(--muted-foreground) / 0.3);
  border-radius: 3px;
}

.custom-scrollbar::-webkit-scrollbar-thumb:hover {
  background: hsl(var(--muted-foreground) / 0.5);
}

/* Thin scrollbar for description areas */
.thin-scrollbar::-webkit-scrollbar {
  width: 4px;
}

.thin-scrollbar::-webkit-scrollbar-track {
  background: transparent;
}

.thin-scrollbar::-webkit-scrollbar-thumb {
  background: hsl(var(--muted-foreground) / 0.2);
  border-radius: 2px;
}

.thin-scrollbar::-webkit-scrollbar-thumb:hover {
  background: hsl(var(--muted-foreground) / 0.4);
}

