import { useState, useMemo } from "react";
import { Search, X, ChevronDown, LayoutGrid, Globe, Tag } from "lucide-react";
import {
  Plane,
  Building2,
  ShoppingBag,
  CreditCard,
  Gift,
  UtensilsCrossed,
  Tv,
  Shield,
  Fuel,
  Gamepad2,
  Music,
  Gem,
  ShoppingCart,
  Home,
} from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { CountryFlag } from "@/components/country-flag";
import { CATEGORIES, COUNTRIES, type Product } from "@shared/schema";

const categoryIcons: Record<string, React.ReactNode> = {
  All: <LayoutGrid className="w-4 h-4" />,
  FLIGHTS: <Plane className="w-4 h-4" />,
  HOTELS: <Building2 className="w-4 h-4" />,
  SHOPPING: <ShoppingBag className="w-4 h-4" />,
  CASHOUTS: <CreditCard className="w-4 h-4" />,
  GIFTCARDS: <Gift className="w-4 h-4" />,
  FOOD: <UtensilsCrossed className="w-4 h-4" />,
  STREAMING: <Tv className="w-4 h-4" />,
  VPN: <Shield className="w-4 h-4" />,
  FUEL: <Fuel className="w-4 h-4" />,
  GAMES: <Gamepad2 className="w-4 h-4" />,
  MUSIC: <Music className="w-4 h-4" />,
  LUXURY: <Gem className="w-4 h-4" />,
  GROCERIES: <ShoppingCart className="w-4 h-4" />,
  RENT: <Home className="w-4 h-4" />,
};

interface UnifiedSearchBarProps {
  searchQuery: string;
  onSearchChange: (value: string) => void;
  selectedCategory: string;
  onCategoryChange: (category: string) => void;
  selectedCountry: string | null;
  onCountryChange: (country: string | null) => void;
  products: Product[];
}

export function UnifiedSearchBar({
  searchQuery,
  onSearchChange,
  selectedCategory,
  onCategoryChange,
  selectedCountry,
  onCountryChange,
  products,
}: UnifiedSearchBarProps) {
  const [categoryOpen, setCategoryOpen] = useState(false);
  const [countryOpen, setCountryOpen] = useState(false);

  const usedCategories = useMemo(() => {
    const cats = new Set(
      products
        .map((p) => p.category)
        .filter((c): c is string => !!c && c.trim() !== "")
    );
    const result: string[] = ["All"];
    CATEGORIES.filter((c) => c !== "All").forEach((cat) => {
      if (cats.has(cat)) result.push(cat);
    });
    cats.forEach((cat) => {
      if (!CATEGORIES.includes(cat as any)) result.push(cat);
    });
    return result;
  }, [products]);

  const availableCountries = useMemo(() => {
    const countryCodes = new Set<string>();
    products.forEach((p) => {
      if (p.countries && p.countries.length > 0) {
        p.countries.forEach((code) => countryCodes.add(code));
      }
    });
    return COUNTRIES.filter((c) => countryCodes.has(c.code));
  }, [products]);

  const hasCategories = usedCategories.length > 1;
  const hasCountries = availableCountries.length > 0;

  const selectedCountryData = selectedCountry
    ? COUNTRIES.find((c) => c.code === selectedCountry)
    : null;

  return (
    <div className="w-full max-w-3xl mx-auto">
      <div className="relative group">
        <div className="absolute -inset-[1px] bg-gradient-to-r from-primary via-primary/80 to-primary rounded-xl opacity-60 group-hover:opacity-100 transition-opacity duration-300" />
        <div className="absolute -inset-[2px] bg-gradient-to-r from-primary/30 via-primary/20 to-primary/30 rounded-xl blur-md opacity-0 group-hover:opacity-60 transition-opacity duration-500" />

        <div className="relative flex items-center bg-background rounded-xl overflow-hidden">
          {hasCategories && (
            <>
              <DropdownMenu open={categoryOpen} onOpenChange={setCategoryOpen}>
                <DropdownMenuTrigger asChild>
                  <button
                    className="flex items-center gap-1.5 px-3 sm:px-4 py-3 text-sm font-medium text-foreground/80 hover:text-foreground hover:bg-primary/5 transition-colors border-r border-primary/10 shrink-0"
                    data-testid="dropdown-category"
                  >
                    <span className="text-primary">
                      {categoryIcons[selectedCategory] || <Tag className="w-4 h-4" />}
                    </span>
                    <span className="hidden sm:inline max-w-[80px] truncate">
                      {selectedCategory === "All" ? "Category" : selectedCategory}
                    </span>
                    <ChevronDown className="w-3.5 h-3.5 text-muted-foreground" />
                  </button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start" className="w-48 max-h-[300px] overflow-y-auto">
                  {usedCategories.map((category) => (
                    <DropdownMenuItem
                      key={category}
                      onClick={() => onCategoryChange(category)}
                      className={`flex items-center gap-2 cursor-pointer ${
                        selectedCategory === category ? "bg-primary/10 text-primary" : ""
                      }`}
                      data-testid={`menu-category-${category.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`}
                    >
                      <span className="text-primary/70">
                        {categoryIcons[category] || <Tag className="w-4 h-4" />}
                      </span>
                      <span className="uppercase text-xs font-semibold tracking-wide">{category}</span>
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            </>
          )}

          <div className="flex-1 flex items-center min-w-0">
            <div className="flex items-center justify-center shrink-0 pl-3 sm:pl-4 text-primary">
              <Search className="w-4 h-4 sm:w-5 sm:h-5" />
            </div>
            <Input
              type="search"
              value={searchQuery}
              onChange={(e) => onSearchChange(e.target.value)}
              placeholder="Search products..."
              className="flex-1 border-0 bg-transparent text-sm sm:text-base text-foreground placeholder:text-muted-foreground/50 focus-visible:ring-0 focus-visible:ring-offset-0 min-w-0"
              data-testid="input-search"
            />
            {searchQuery && (
              <Button
                variant="ghost"
                size="icon"
                className="shrink-0 text-muted-foreground h-8 w-8"
                onClick={() => onSearchChange("")}
                data-testid="button-clear-search"
              >
                <X className="w-4 h-4" />
              </Button>
            )}
          </div>

          {hasCountries && (
            <>
              <DropdownMenu open={countryOpen} onOpenChange={setCountryOpen}>
                <DropdownMenuTrigger asChild>
                  <button
                    className="flex items-center gap-1.5 px-3 sm:px-4 py-3 text-sm font-medium text-foreground/80 hover:text-foreground hover:bg-primary/5 transition-colors border-l border-primary/10 shrink-0"
                    data-testid="dropdown-country"
                  >
                    {selectedCountryData ? (
                      <CountryFlag code={selectedCountryData.code} size="sm" />
                    ) : (
                      <Globe className="w-4 h-4 text-primary" />
                    )}
                    <span className="hidden sm:inline max-w-[80px] truncate">
                      {selectedCountryData ? selectedCountryData.name : "Region"}
                    </span>
                    <ChevronDown className="w-3.5 h-3.5 text-muted-foreground" />
                  </button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="end" className="w-56 max-h-[300px] overflow-y-auto">
                  <DropdownMenuItem
                    onClick={() => onCountryChange(null)}
                    className={`flex items-center gap-2 cursor-pointer ${
                      selectedCountry === null ? "bg-primary/10 text-primary" : ""
                    }`}
                    data-testid="menu-country-all"
                  >
                    <div className="w-5 h-5 rounded-full bg-gradient-to-br from-primary to-accent flex items-center justify-center text-[10px] font-bold text-primary-foreground">
                      A
                    </div>
                    <span className="font-medium">All Regions</span>
                  </DropdownMenuItem>
                  {availableCountries.map((country) => (
                    <DropdownMenuItem
                      key={country.code}
                      onClick={() => onCountryChange(country.code)}
                      className={`flex items-center gap-2 cursor-pointer ${
                        selectedCountry === country.code ? "bg-primary/10 text-primary" : ""
                      }`}
                      data-testid={`menu-country-${country.code}`}
                    >
                      <CountryFlag code={country.code} size="sm" />
                      <span>{country.name}</span>
                    </DropdownMenuItem>
                  ))}
                </DropdownMenuContent>
              </DropdownMenu>
            </>
          )}
        </div>
      </div>

      {(selectedCategory !== "All" || selectedCountry !== null) && (
        <div className="flex items-center justify-center gap-2 mt-3 flex-wrap">
          {selectedCategory !== "All" && (
            <button
              onClick={() => onCategoryChange("All")}
              className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-primary/10 text-primary text-xs font-medium hover:bg-primary/20 transition-colors"
              data-testid="chip-category-active"
            >
              {categoryIcons[selectedCategory] || <Tag className="w-3 h-3" />}
              <span className="uppercase tracking-wide">{selectedCategory}</span>
              <X className="w-3 h-3" />
            </button>
          )}
          {selectedCountry !== null && selectedCountryData && (
            <button
              onClick={() => onCountryChange(null)}
              className="flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-primary/10 text-primary text-xs font-medium hover:bg-primary/20 transition-colors"
              data-testid="chip-country-active"
            >
              <CountryFlag code={selectedCountryData.code} size="sm" />
              <span>{selectedCountryData.name}</span>
              <X className="w-3 h-3" />
            </button>
          )}
        </div>
      )}
    </div>
  );
}

client/src/components/announcement-bar.t.content:
import { useState, useEffect, useMemo, useCallback } from "react";
import { useQuery } from "@tanstack/react-query";
import { queryClient } from "@/lib/queryClient";
import { ChevronLeft, ChevronRight, Sparkles } from "lucide-react";

interface ShopSettings {
  announcementEnabled: boolean;
  announcementText: string;
}

export function AnnouncementBar() {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [phase, setPhase] = useState<"enter" | "visible" | "exit">("enter");

  const { data: settings } = useQuery<ShopSettings>({
    queryKey: ["/api/settings/shop"],
  });

  const messages = useMemo(() => {
    if (!settings?.announcementText?.trim()) return [];
    return settings.announcementText.split("/n").map(m => m.trim()).filter(Boolean);
  }, [settings?.announcementText]);

  useEffect(() => {
    if (messages.length <= 1 && phase === "visible") return;

    if (phase === "enter") {
      const t = requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          setPhase("visible");
        });
      });
      return () => cancelAnimationFrame(t);
    }
    if (phase === "visible") {
      const t = setTimeout(() => setPhase("exit"), 3000);
      return () => clearTimeout(t);
    }
    if (phase === "exit") {
      const t = setTimeout(() => {
        setCurrentIndex(prev => (prev + 1) % messages.length);
        setPhase("enter");
      }, 500);
      return () => clearTimeout(t);
    }
  }, [phase, messages.length]);

  const goToNext = useCallback(() => {
    if (messages.length <= 1 || phase === "exit") return;
    setPhase("exit");
  }, [messages.length, phase]);

  const goToPrev = useCallback(() => {
    if (messages.length <= 1 || phase === "exit") return;
    setPhase("exit");
    setTimeout(() => {
      setCurrentIndex(prev => (prev - 1 + messages.length) % messages.length);
      setPhase("enter");
    }, 500);
  }, [messages.length, phase]);

  useEffect(() => {
    const handleUpdate = () => {
      queryClient.invalidateQueries({ queryKey: ["/api/settings/shop"] });
    };
    window.addEventListener("shopSettingsUpdated", handleUpdate);
    return () => window.removeEventListener("shopSettingsUpdated", handleUpdate);
  }, []);

  if (!settings?.announcementEnabled || messages.length === 0) {
    return null;
  }

  return (
    <div className="w-full mb-3 sm:mb-4" data-testid="announcement-bar">
      <div className="mx-auto max-w-7xl px-4 sm:px-6">
        <div className="relative group">
          <div
            className="absolute -inset-[1px] rounded-xl opacity-75 blur-[2px] transition-all duration-500 group-hover:opacity-100 group-hover:blur-[3px]"
            style={{
              background: "linear-gradient(90deg, hsl(var(--primary) / 0.6), hsl(var(--primary) / 0.2), hsl(var(--primary) / 0.6))",
              backgroundSize: "200% 100%",
              animation: "announcementGradientMove 3s linear infinite",
            }}
          />

          <div className="relative flex items-center rounded-xl bg-gradient-to-r from-background/95 via-card/90 to-background/95 backdrop-blur-md border border-primary/15 overflow-hidden">
            <div
              className="absolute inset-0 opacity-[0.03]"
              style={{
                backgroundImage: "radial-gradient(circle at 20% 50%, hsl(var(--primary)), transparent 50%), radial-gradient(circle at 80% 50%, hsl(var(--primary)), transparent 50%)",
              }}
            />

            <div className="absolute left-0 top-0 bottom-0 w-12 sm:w-16 flex items-center justify-center z-10">
              <div className="relative">
                <Sparkles className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-primary/70" />
                <div className="absolute inset-0 animate-ping">
                  <Sparkles className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-primary/20" />
                </div>
              </div>
            </div>

            {messages.length > 1 && (
              <button
                onClick={goToPrev}
                className="relative z-10 flex-shrink-0 p-2 sm:p-2.5 ml-8 sm:ml-12 rounded-md text-primary/50 hover:text-primary hover:bg-primary/10 transition-all duration-200"
                data-testid="button-announcement-prev"
              >
                <ChevronLeft className="w-4 h-4" />
              </button>
            )}

            <div className={`flex-1 overflow-hidden py-3 sm:py-3.5 ${messages.length <= 1 ? 'ml-12 sm:ml-16' : ''}`}>
              <div className="relative flex items-center justify-center min-h-[1.5rem]">
                <p
                  className={`text-sm sm:text-[0.9rem] text-foreground/90 font-medium tracking-wide text-center transition-all ease-in-out ${
                    phase === "enter"
                      ? "translate-x-[120%] opacity-0"
                      : phase === "visible"
                        ? "translate-x-0 opacity-100"
                        : "-translate-x-[120%] opacity-0"
                  }`}
                  style={{ transitionDuration: phase === "enter" ? "0ms" : "500ms" }}
                  data-testid="text-announcement-message"
                >
                  {messages[currentIndex]}
                </p>
              </div>
            </div>

            {messages.length > 1 && (
              <button
                onClick={goToNext}
                className="relative z-10 flex-shrink-0 p-2 sm:p-2.5 mr-8 sm:mr-12 rounded-md text-primary/50 hover:text-primary hover:bg-primary/10 transition-all duration-200"
                data-testid="button-announcement-next"
              >
                <ChevronRight className="w-4 h-4" />
              </button>
            )}

            <div className="absolute right-0 top-0 bottom-0 w-12 sm:w-16 flex items-center justify-center z-10">
              <div className="relative">
                <Sparkles className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-primary/70" />
                <div className="absolute inset-0 animate-ping" style={{ animationDelay: "1s" }}>
                  <Sparkles className="w-3.5 h-3.5 sm:w-4 sm:h-4 text-primary/20" />
                </div>
              </div>
            </div>

            {messages.length > 1 && (
              <div className="absolute bottom-1 left-1/2 -translate-x-1/2 flex gap-1">
                {messages.map((_, i) => (
                  <div
                    key={i}
                    className={`h-[3px] rounded-full transition-all duration-300 ${
                      i === currentIndex
                        ? "w-4 bg-primary/60"
                        : "w-1.5 bg-primary/20"
                    }`}
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      <style>{`
        @keyframes announcementGradientMove {
          0% { background-position: 0% 0%; }
          100% { background-position: 200% 0%; }
        }
      `}</style>
    </div>
  );
}
